ALTER TABLE cm_ads ADD COLUMN cards_json TEXT NOT NULL DEFAULT '{}';
INSERT INTO changelog (title, body, created_at) VALUES ('Карусель: тексти кожної картки', 'У каруселі кожна картка тепер має свій заголовок (до 40 символів), опис (до 20) і посилання — у розділі «Тексти оголошення» під основним текстом, з кнопками «Копіювати» і лічильниками. «Тексти під цей креатив» Джері заповнює картки сам, дивлячись на кожну. Порожнє посилання картки = посилання оголошення. Перевірка перед запуском підкаже, де картка без заголовка.', datetime('now'));
